def solve(inputs: dict) -> float:
    terms = inputs['terms']

    # Initialize
    p_prev2 = 1      # p_{-1}
    p_prev1 = terms[0]  # p_0

    # Compute numerators
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

